import {describe, it, expect} from 'vitest';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

describe('ChatOrchestrator usage accumulation', () => {
  const promptBuilder = new PromptBuilder({identity: 'Test.'});
  const session = (): ChatSession => ({
    sessionId: 's',
    userId: 'u',
    entries: [{role: 'user', content: 'c', timestamp: new Date().toISOString()}],
  });

  const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: '1', name: 't', input: {}}};
  const usageStop = (stopReason: string, usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason, usage});

  const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
    let round = 0;
    return {
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        yield* rounds[round++] ?? [];
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
  };

  it('accumulates usage across multiple rounds', async () => {
    let capturedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_s, _t, usage) => {
        capturedUsage = usage;
      },
    };

    const registry = new ToolRegistry();
    registry.register({name: 't', description: 'd', inputSchema: {}}, async () => 'r');

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 10, outputTokens: 5, totalTokens: 15})],
        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 20, outputTokens: 10, totalTokens: 30})],
      ]),
      promptBuilder,
      registry,
      {hooks}
    );

    await orchestrator.processMessage(session());

    // Current behavior (FAILING): it will be {inputTokens: 20, outputTokens: 10, totalTokens: 30}
    // Expected behavior: {inputTokens: 30, outputTokens: 15, totalTokens: 45}
    expect(capturedUsage).toEqual({
      inputTokens: 30,
      outputTokens: 15,
      totalTokens: 45,
    });
  });
});

